fast_pseudocode:
# GOOD: Cap R0_BLOCK at 256 → Welford state = 16×256×3×4 = 48KB, fits in L1
@triton.autotune(configs=[
    triton.Config({'XBLOCK': 16, 'R0_BLOCK': 256}, num_warps=4, num_stages=1),
    triton.Config({'XBLOCK': 16, 'R0_BLOCK': 128}, num_warps=4, num_stages=1),
    triton.Config({'XBLOCK': 32, 'R0_BLOCK': 256}, num_warps=8, num_stages=1),
    triton.Config({'XBLOCK': 8,  'R0_BLOCK': 256}, num_warps=4, num_stages=2),
])
def kernel(...):
    # Welford accumulators stay in registers/L1
    mean, m2, weight = welford_reduce(data)

